def is_undulating(number: int) -> bool:
    """
    Checks if a number is undulating. 
    An undulating number is a number where the digits alternate 
    between two values (e.g., 1212121, 35353).
    """
    s = str(number)
    if len(s) < 2:
        return True

    # Identify the first two digits to establish the pattern
    first = s[0]
    second = s[1]

    # If the first two digits are the same, it's not undulating 
    # (unless it's a single digit, handled above)
    if first == second:
        return False

    for i in range(len(s)):
        # Even indices should match the first digit
        # Odd indices should match the second digit
        if i % 2 == 0:
            if s[i] != first:
                return False
        else:
            if s[i] != second:
                return False

    return True

