    s = str(n)
    if len(s) < 3:
        return False

    for i in range(1, len(s) - 1):
        prev = int(s[i-1])
        curr = int(s[i])
        nxt = int(s[i+1])

        # Check if the current digit is strictly between the neighbors
        # and ensure it follows the alternating pattern (up-down-up or down-up-down)
        if not ((prev < curr > nxt) or (prev > curr < nxt)):
            return False

    # Additional check to ensure adjacent digits are not equal
    for i in range(len(s) - 1):
        if s[i] == s[i+1]:
            return False

    return True
